import os
from azure.cognitiveservices.speech import SpeechConfig, AudioConfig

def get_speech_config():
    subscription_key = os.getenv('SPEECH_KEY')
    region = os.getenv('SPEECH_REGION')
    return SpeechConfig(subscription=subscription_key, region=region)

def get_audio_config(use_default_microphone=True):
    return AudioConfig(use_default_microphone=use_default_microphone)

from azure.cognitiveservices.speech import SpeechRecognitionResult, SpeechRecognitionCanceled

def normalize_recognition_result(result):
    if isinstance(result, SpeechRecognitionResult):
        return result.text
    elif isinstance(result, SpeechRecognitionCanceled):
        return 'Canceled: {}'.format(result.cancellation_details.error_details)
    else:
        return 'Unknown result type'

import azure.cognitiveservices.speech as speechsdk

def translate_caption(caption, target_language='es'):
    speech_config = speechsdk.SpeechConfig(subscription="YourSubscriptionKey", region="YourServiceRegion")
    speech_synthesizer = speechsdk.SpeechSynthesizer(speech_config=speech_config, language=target_language)
    result = speech_synthesizer.speak_text_async(caption).get()
    if result.reason == speechsdk.ResultReason.SynthesizingAudioCompleted:
        return result.audio_data
    else:
        print('Speech synthesis canceled: {}'.format(result.cancellation_details.reason))
